// Vulkan backend for the device layer.
//
// Bring-up (loader, instance, physical device, queues, surface, swapchain,
// command buffers, synchronisation), the frame, and every entry point of the
// device interface - the dispatch table s_gfxVK at the end of this file.
//
// Nothing links against vulkan-1. Every entry point is fetched through
// SDL_Vulkan_GetVkGetInstanceProcAddr, which is why VK_NO_PROTOTYPES is set
// before the header - with prototypes we would get link-time references to a
// library that, for a 32-bit build, the SDK does not even ship.
//
// Two rules followed throughout, because this code cannot be run from where it
// is written:
//
//   Every Vulkan call that can fail is checked and says which call failed.
//   The validation layer is enabled when asked for (--vk-validation) and
//   installed. It used to be on whenever it was installed - which on the
//   development machine meant every run, play sessions and performance
//   measurements included; see g_cfg_vkValidation.
//
// A silent black screen is the one outcome that teaches nothing.

#define VK_NO_PROTOTYPES
#include <vulkan/vulkan.h>

#include <SDL3/SDL.h>
#include <SDL3/SDL_vulkan.h>

#include "platform/native_log.h"

// The device interface this backend implements. The pipeline cache also needs
// its state vocabulary - blend modes, vertex attribute types - to key on.
#include "platform/native_gfx_dispatch.h"

// Generated by the build from platform/native_shaders.inc - the shader bodies,
// assembled by tools/shader_spirv_probe.c and turned into SPIR-V.
#include "native_shaders_spv.h"

#if defined(_WIN32)
// For the sibling-SDK scan in NativeVk_PointLoaderAtSdkLayers.
#include <windows.h>
#endif

#include <stdio.h>
#include <string.h>

#define NATIVE_VK_MAX_SWAPCHAIN_IMAGES 8

// Two frames in flight: the CPU may prepare the next while the GPU works on the
// current. More would add latency for no gain at the frame rates involved.
#define NATIVE_VK_FRAMES_IN_FLIGHT 2

// --- Entry points -----------------------------------------------------------
//
// Three tiers, because that is how Vulkan hands them out. Global ones come from
// a NULL instance, instance ones from the instance, device ones from the device
// - and device-level pointers fetched per device skip the loader's dispatch
// hop, which is the reason the split exists at all.

#define NATIVE_VK_GLOBAL_FUNCS       \
	X(vkCreateInstance)                \
	X(vkEnumerateInstanceLayerProperties) \
	X(vkEnumerateInstanceExtensionProperties)

#define NATIVE_VK_INSTANCE_FUNCS               \
	X(vkDestroyInstance)                         \
	X(vkEnumeratePhysicalDevices)                \
	X(vkEnumerateDeviceExtensionProperties)      \
	X(vkGetPhysicalDeviceFormatProperties)       \
	X(vkGetPhysicalDeviceImageFormatProperties)  \
	X(vkGetPhysicalDeviceProperties)             \
	X(vkGetPhysicalDeviceFeatures)               \
	X(vkGetPhysicalDeviceQueueFamilyProperties)  \
	X(vkGetPhysicalDeviceSurfaceSupportKHR)      \
	X(vkGetPhysicalDeviceSurfaceCapabilitiesKHR) \
	X(vkGetPhysicalDeviceSurfaceFormatsKHR)      \
	X(vkGetPhysicalDeviceSurfacePresentModesKHR) \
	X(vkCreateDevice)                            \
	X(vkGetDeviceProcAddr)                       \
	X(vkGetPhysicalDeviceMemoryProperties)       \
	X(vkDestroySurfaceKHR)

#define NATIVE_VK_DEVICE_FUNCS   \
	X(vkDestroyDevice)             \
	X(vkDeviceWaitIdle)            \
	X(vkGetDeviceQueue)            \
	X(vkCreateSwapchainKHR)        \
	X(vkDestroySwapchainKHR)       \
	X(vkGetSwapchainImagesKHR)     \
	X(vkAcquireNextImageKHR)       \
	X(vkQueuePresentKHR)           \
	X(vkCreateImageView)           \
	X(vkDestroyImageView)          \
	X(vkCreateRenderPass)          \
	X(vkDestroyRenderPass)         \
	X(vkCreateFramebuffer)         \
	X(vkDestroyFramebuffer)        \
	X(vkCreateCommandPool)         \
	X(vkDestroyCommandPool)        \
	X(vkAllocateCommandBuffers)    \
	X(vkResetCommandBuffer)        \
	X(vkBeginCommandBuffer)        \
	X(vkEndCommandBuffer)          \
	X(vkCmdBeginRenderPass)        \
	X(vkCmdEndRenderPass)          \
	X(vkCreateSemaphore)           \
	X(vkDestroySemaphore)          \
	X(vkCreateFence)               \
	X(vkDestroyFence)              \
	X(vkWaitForFences)             \
	X(vkResetFences)               \
	X(vkQueueSubmit)               \
	X(vkQueueWaitIdle)             \
	X(vkCreateBuffer)              \
	X(vkDestroyBuffer)             \
	X(vkGetBufferMemoryRequirements) \
	X(vkBindBufferMemory)          \
	X(vkAllocateMemory)            \
	X(vkFreeMemory)                \
	X(vkMapMemory)                 \
	X(vkUnmapMemory)               \
	X(vkCreateImage)               \
	X(vkDestroyImage)              \
	X(vkGetImageMemoryRequirements) \
	X(vkBindImageMemory)           \
	X(vkCreateSampler)             \
	X(vkDestroySampler)            \
	X(vkCreateDescriptorSetLayout) \
	X(vkDestroyDescriptorSetLayout) \
	X(vkCreateDescriptorPool)      \
	X(vkDestroyDescriptorPool)     \
	X(vkAllocateDescriptorSets)    \
	X(vkUpdateDescriptorSets)      \
	X(vkCreateShaderModule)        \
	X(vkDestroyShaderModule)       \
	X(vkCreatePipelineLayout)      \
	X(vkDestroyPipelineLayout)     \
	X(vkCreateGraphicsPipelines)   \
	X(vkDestroyPipeline)           \
	X(vkCmdPipelineBarrier)        \
	X(vkCmdCopyBufferToImage)      \
	X(vkCmdBindPipeline)           \
